Lemma small_facts : forall n, 1 <= n <= 448 ->
  is_primary n = true /\ needed_size n = rounded_size n + rz_size n
  /\ 16 <= rz_size n <= 64 /\ rz_size n = 16 * 2 ^ rz_log n
  /\ Z.max n 8 <= rounded_size n <= Z.max n 8 + 7 /\ rounded_size n mod 8 = 0
